// ============================================================================
// sync-live-settle â€” combined live scores + kill-switch settlement (cron)
// ----------------------------------------------------------------------------
// Port of scripts/sync-live-settle.ts for Supabase Edge + Cron.
//
// Gatekeeper: query matches first. If no catalog match is `live` or `upcoming`
// with kickoff in the last 3 hours â†’ return immediately (0 API calls).
//
// Poll shape (per active sport), then filter to LEAGUE_CATALOG client-side:
//   football â†’ GET /fixtures?live=all  (freshest minute/score; no date cache)
//   rugby    â†’ GET /games?date=YYYY-MM-DD
//
// Kill switch: FT/AET/PEN/AWD â†’ actual scores, status=completed, clear minute,
// grade predictions. Completed matches never re-enter the active window.
//
// Invoke (POST or GET â€” Cron-friendly). Optional JSON body ignored.
//
// Required secrets:
//   API_SPORTS_KEY
//   SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY (auto-injected on hosted)
// Optional:
//   API_SPORTS_MIN_INTERVAL_MS (default 7000)
//   API_SPORTS_DAILY_BUDGET (default 7000)
// ============================================================================

import { createClient, type SupabaseClient } from "npm:@supabase/supabase-js@2";
import {
  ApiSportsClient,
  DAILY_BUDGET_CAP,
  UpstreamAuthError,
  getApiSportsKey,
  utcDay,
  type Sport,
} from "../_shared/apiSportsClient.ts";
import {
  FOOTBALL_API_IDS,
  FOOTBALL_LEAGUES,
  FOOTBALL_SLUG_BY_API,
} from "../_shared/footballLeagues.ts";

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
};

/** ONLY these API-Sports league IDs are monitored / settled. */
const LEAGUE_CATALOG: Record<Sport, readonly number[]> = {
  football: FOOTBALL_LEAGUES.map((l) => l.apiId),
  rugby: [13, 16, 22, 14, 15, 26, 19, 10],
};

const SLUG_BY_SPORT_AND_API: Record<string, string> = {
  ...FOOTBALL_SLUG_BY_API,
  "rugby:13": "r-top14",
  "rugby:16": "r-prem",
  "rugby:26": "r-urc",
  "rugby:22": "r-sixnations",
  "rugby:14": "r-championship",
  "rugby:15": "r-nations",
  "rugby:19": "r-heineken",
  "rugby:10": "r-worldcup",
};

const CATALOG_SETS: Record<Sport, ReadonlySet<number>> = {
  football: FOOTBALL_API_IDS,
  rugby: new Set(LEAGUE_CATALOG.rugby),
};

const CATALOG_COMPETITION_IDS: string[] = [
  ...FOOTBALL_LEAGUES.map((l) => l.slug),
  ...LEAGUE_CATALOG.rugby.map(
    (id) => SLUG_BY_SPORT_AND_API[`rugby:${id}`] || `rugby-${id}`,
  ),
];

/** Kickoff lookback for still-`upcoming` rows that should already be underway. */
const ACTIVE_KICKOFF_LOOKBACK_MS = 3 * 60 * 60 * 1000;

const LIVE_STATUSES = new Set([
  "1H",
  "2H",
  "HT",
  "LIVE",
  "ET",
  "BT",
  "P",
  "INT",
  "SUSP",
]);

const FOOTBALL_FINISHED = new Set(["FT", "AET", "PEN", "AWD", "WO"]);
const RUGBY_FINISHED = new Set([
  "FT",
  "FINISHED",
  "ENDED",
  "AET",
  "AWD",
  "WO",
  "PEN",
]);

type DbMatch = {
  id: string;
  sport: Sport;
  status: string;
  kickoff_time: string | null;
  competition_id: string | null;
  base_multiplier: number | null;
};

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...CORS_HEADERS, "Content-Type": "application/json" },
  });
}

function statusShort(item: any): string {
  const fixture = item.fixture ?? item;
  return String(fixture.status?.short ?? item.status?.short ?? "").toUpperCase();
}

function statusLong(item: any): string {
  const fixture = item.fixture ?? item;
  return String(fixture.status?.long ?? item.status?.long ?? "").toUpperCase();
}

function leagueIdFromItem(item: any): number | null {
  const id = item?.league?.id ?? item?.league_id ?? null;
  if (id == null) return null;
  const n = Number(id);
  return Number.isFinite(n) ? n : null;
}

function apiFixtureId(item: any): number | string | null {
  const fixture = item.fixture ?? item;
  return fixture.id ?? item.id ?? null;
}

function formatMatchMinute(item: any): string | null {
  const fixture = item.fixture ?? item;
  const elapsed = fixture.status?.elapsed ?? item.status?.elapsed;
  if (elapsed != null && elapsed !== "") return `${elapsed}'`;
  const short = statusShort(item);
  return short || null;
}

function isFinished(sport: Sport, item: any): boolean {
  const short = statusShort(item);
  const long = statusLong(item);
  if (sport === "football") return FOOTBALL_FINISHED.has(short);
  return (
    RUGBY_FINISHED.has(short) ||
    long === "FINISHED" ||
    long.includes("FINISHED")
  );
}

function isLiveStatus(item: any): boolean {
  return LIVE_STATUSES.has(statusShort(item));
}

function extractLiveScores(
  item: any,
): { home: number | null; away: number | null } {
  // Football (verified): goals.home / goals.away. Rugby uses scores.*.
  const goals = item.goals ?? item.scores ?? {};
  return {
    home: goals.home != null ? Number(goals.home) : null,
    away: goals.away != null ? Number(goals.away) : null,
  };
}

function extractFootballFinalScores(
  item: any,
): { home: number; away: number } | null {
  const fixture = item.fixture ?? item;
  const short = statusShort(item);
  const score = item.score ?? fixture.score ?? {};
  const goals = item.goals ?? {};

  if (short === "PEN" || short === "AET") {
    const extra = score.extratime;
    if (extra?.home != null && extra?.away != null) {
      return { home: Number(extra.home), away: Number(extra.away) };
    }
  }

  if (goals.home != null && goals.away != null) {
    return { home: Number(goals.home), away: Number(goals.away) };
  }

  const fulltime = score.fulltime;
  if (fulltime?.home != null && fulltime?.away != null) {
    return { home: Number(fulltime.home), away: Number(fulltime.away) };
  }
  return null;
}

function extractRugbyFinalScores(
  item: any,
): { home: number; away: number } | null {
  const scores = item.scores ?? item.fixture?.scores;
  if (scores?.home != null && scores?.away != null) {
    return { home: Number(scores.home), away: Number(scores.away) };
  }
  return null;
}

function extractFinalScores(
  sport: Sport,
  item: any,
): { home: number; away: number } | null {
  return sport === "football"
    ? extractFootballFinalScores(item)
    : extractRugbyFinalScores(item);
}

function calculateFootballPoints(
  predictedHome: number,
  predictedAway: number,
  actualHome: number,
  actualAway: number,
): number {
  const predictedWinner = predictedHome > predictedAway
    ? "home"
    : predictedHome < predictedAway
    ? "away"
    : "draw";
  const actualWinner = actualHome > actualAway
    ? "home"
    : actualHome < actualAway
    ? "away"
    : "draw";
  if (predictedWinner !== actualWinner) return 0;
  if (predictedHome === actualHome && predictedAway === actualAway) return 5;
  if (predictedHome - predictedAway === actualHome - actualAway) return 3;
  return 1;
}

function calculateRugbyPoints(
  predictedHome: number,
  predictedAway: number,
  actualHome: number,
  actualAway: number,
): number {
  const predictedWinner = predictedHome > predictedAway
    ? "home"
    : predictedHome < predictedAway
    ? "away"
    : "draw";
  const actualWinner = actualHome > actualAway
    ? "home"
    : actualHome < actualAway
    ? "away"
    : "draw";
  if (predictedWinner !== actualWinner) return 0;
  const marginDifference = Math.abs(
    Math.abs(predictedHome - predictedAway) -
      Math.abs(actualHome - actualAway),
  );
  if (marginDifference === 0) return 5;
  if (marginDifference <= 7) return 3;
  if (marginDifference <= 10) return 1;
  return 0;
}

type PowerUpType =
  | "double_bubble"
  | "safety_net"
  | "sniper"
  | "banker"
  | "pitchside_master";

const EXACT_SCORE_POINTS = 5;
const SAFETY_FLOOR = 5;

/** Keep in sync with sync-settlement / scoringEngine / pitchside_apply_powerup. */
function applyPowerUp(
  basePoints: number,
  powerup: PowerUpType | null | undefined,
  predictedHome: number,
  predictedAway: number,
  actualHome: number,
  actualAway: number,
): { points: number; isBankerExact: boolean } {
  let points = basePoints;
  let isBankerExact = false;

  const predictedWinner = predictedHome > predictedAway
    ? "home"
    : predictedHome < predictedAway
    ? "away"
    : "draw";
  const actualWinner = actualHome > actualAway
    ? "home"
    : actualHome < actualAway
    ? "away"
    : "draw";
  const outcomeCorrect = predictedWinner === actualWinner;
  const isExact = predictedHome === actualHome && predictedAway === actualAway;

  if (powerup === "banker") {
    if (outcomeCorrect) {
      points = EXACT_SCORE_POINTS;
      isBankerExact = true;
    }
  } else if (powerup === "sniper" && isExact) {
    points = Math.round(points * 1.5);
  }

  if (powerup === "double_bubble") points *= 2;
  else if (powerup === "pitchside_master") points *= 3;

  if (powerup === "safety_net" && points === 0) points = SAFETY_FLOOR;

  return { points, isBankerExact };
}

function applyMultiplier(
  basePoints: number,
  multiplier: number | null,
): number {
  const factor = multiplier != null && multiplier > 0 ? Number(multiplier) : 1;
  return Math.round(basePoints * factor);
}

/**
 * Gatekeeper: catalog matches that are `live`, OR `upcoming` with kickoff
 * in the last 3 hours. Completed rows never qualify.
 */
async function loadActiveCatalogMatches(
  supabase: SupabaseClient,
): Promise<DbMatch[]> {
  const sinceIso = new Date(Date.now() - ACTIVE_KICKOFF_LOOKBACK_MS)
    .toISOString();
  const nowIso = new Date().toISOString();

  const { data: liveRows, error: liveErr } = await supabase
    .from("matches")
    .select("id, sport, status, kickoff_time, competition_id, base_multiplier")
    .eq("status", "live")
    .in("competition_id", CATALOG_COMPETITION_IDS);

  if (liveErr) {
    console.warn(`[sync-live-settle] live query failed: ${liveErr.message}`);
  }

  const { data: upcomingRows, error: upErr } = await supabase
    .from("matches")
    .select("id, sport, status, kickoff_time, competition_id, base_multiplier")
    .eq("status", "upcoming")
    .gte("kickoff_time", sinceIso)
    .lte("kickoff_time", nowIso)
    .in("competition_id", CATALOG_COMPETITION_IDS);

  if (upErr) {
    console.warn(`[sync-live-settle] upcoming query failed: ${upErr.message}`);
  }

  const byId = new Map<string, DbMatch>();
  for (const row of [...(liveRows || []), ...(upcomingRows || [])]) {
    if (row.sport !== "football" && row.sport !== "rugby") continue;
    byId.set(row.id, row as DbMatch);
  }
  return Array.from(byId.values());
}

async function gradePredictions(
  supabase: SupabaseClient,
  sport: Sport,
  matchId: string,
  actualHome: number,
  actualAway: number,
  multiplier: number | null,
): Promise<number> {
  const { data: predictions, error } = await supabase
    .from("predictions")
    .select(
      "id, user_id, predicted_home_score, predicted_away_score, applied_powerup_id",
    )
    .eq("match_id", matchId);

  if (error) {
    console.warn(
      `[sync-live-settle] prediction fetch failed for ${matchId}: ${error.message}`,
    );
    return 0;
  }

  const powerupIds = [
    ...new Set(
      (predictions ?? [])
        .map((p) => p.applied_powerup_id as string | null)
        .filter((id): id is string => !!id),
    ),
  ];
  const powerupTypeById = new Map<string, PowerUpType>();
  if (powerupIds.length > 0) {
    const { data: chips } = await supabase
      .from("user_powerups")
      .select("id, powerup_type")
      .in("id", powerupIds);
    for (const chip of chips ?? []) {
      powerupTypeById.set(chip.id, chip.powerup_type as PowerUpType);
    }
  }

  let graded = 0;
  for (const pred of predictions ?? []) {
    const powerupType = pred.applied_powerup_id
      ? powerupTypeById.get(pred.applied_powerup_id) ?? null
      : null;
    const base = sport === "football"
      ? calculateFootballPoints(
        pred.predicted_home_score,
        pred.predicted_away_score,
        actualHome,
        actualAway,
      )
      : calculateRugbyPoints(
        pred.predicted_home_score,
        pred.predicted_away_score,
        actualHome,
        actualAway,
      );
    const powered = applyPowerUp(
      base,
      powerupType,
      pred.predicted_home_score,
      pred.predicted_away_score,
      actualHome,
      actualAway,
    );
    const pointsWon = applyMultiplier(powered.points, multiplier);
    const { error: updErr } = await supabase
      .from("predictions")
      .update({
        points_won: pointsWon,
        is_banker_exact: powered.isBankerExact,
      })
      .eq("id", pred.id);
    if (updErr) {
      console.warn(
        `[sync-live-settle] prediction update failed ${pred.id}: ${updErr.message}`,
      );
      continue;
    }

    // Chip is normally marked used at lock time; keep settlement idempotent.
    if (pred.applied_powerup_id) {
      await supabase
        .from("user_powerups")
        .update({
          status: "used",
          used_at: new Date().toISOString(),
          applied_fixture_id: matchId,
        })
        .eq("id", pred.applied_powerup_id)
        .eq("status", "available");
    }

    graded++;
  }
  return graded;
}

async function processSport(
  sport: Sport,
  client: ApiSportsClient,
  supabase: SupabaseClient,
  knownById: Map<string, DbMatch>,
): Promise<{
  liveUpdated: number;
  settled: number;
  predictionsGraded: number;
  fetched: number;
}> {
  const today = utcDay();
  const apiPath = sport === "football" ? "/fixtures" : "/games";
  // Football: live=all for freshest minute/score ticks (bypass date-window cache).
  // Rugby: keep date=today (rugby API has no equivalent live=all shape here).
  const params: Record<string, string> = sport === "football"
    ? { live: "all" }
    : { date: today };
  const label = sport === "football"
    ? `live-settle ${sport} live=all`
    : `live-settle ${sport} date=${today}`;
  const catalog = CATALOG_SETS[sport];

  console.log(
    `[sync-live-settle] Fetching ${sport} ${apiPath}?${
      sport === "football" ? "live=all" : `date=${today}`
    }`,
  );

  const result = await client.get(sport, apiPath, params, label);

  if (!result.ok) {
    if (result.reason === "auth_failure") {
      throw new UpstreamAuthError(result.status ?? 401, "sync-live-settle");
    }
    if (result.reason === "budget_exhausted") {
      console.warn(
        `[sync-live-settle] Budget exhausted for ${sport} â€” skipping (calls_made=${result.callsMadeToday}/${DAILY_BUDGET_CAP})`,
      );
    } else if (result.reason === "plan_blocked") {
      console.warn(
        `[sync-live-settle] Subscription / plan block for ${sport}: ${result.message}`,
      );
    } else if (result.reason === "validation_error") {
      console.warn(
        `[sync-live-settle] API validation error for ${sport}: ${result.message}`,
      );
    } else {
      console.warn(
        `[sync-live-settle] API error for ${sport} (${result.reason}): ${result.message}`,
      );
    }
    return { liveUpdated: 0, settled: 0, predictionsGraded: 0, fetched: 0 };
  }

  const fixtures: any[] = Array.isArray(result.json?.response)
    ? result.json.response
    : [];

  const catalogItems = fixtures.filter((item) => {
    const leagueId = leagueIdFromItem(item);
    return leagueId != null && catalog.has(leagueId);
  });

  let liveUpdated = 0;
  let settled = 0;
  let predictionsGraded = 0;
  const nowIso = new Date().toISOString();

  for (const item of catalogItems) {
    const apiId = apiFixtureId(item);
    if (apiId == null) continue;
    const matchId = `${sport}-${apiId}`;
    const known = knownById.get(matchId);

    if (!known) continue;
    if (known.status === "completed") continue;

    if (isFinished(sport, item)) {
      const scores = extractFinalScores(sport, item);
      if (!scores) {
        console.warn(
          `[sync-live-settle] Finished ${matchId} but could not read final scores â€” skipping`,
        );
        continue;
      }

      const externalFixtureId = Number.isFinite(Number(apiId))
        ? Number(apiId)
        : null;
      const { error } = await supabase
        .from("matches")
        .update({
          status: "completed",
          external_fixture_id: externalFixtureId,
          actual_home_score: scores.home,
          actual_away_score: scores.away,
          provisional_home_score: null,
          provisional_away_score: null,
          match_minute: null,
          updated_at: nowIso,
        })
        .eq("id", matchId)
        .neq("status", "completed");

      if (error) {
        console.warn(
          `[sync-live-settle] settle update failed ${matchId}: ${error.message}`,
        );
        continue;
      }

      settled++;
      known.status = "completed";
      console.log(
        `[sync-live-settle] KILL SWITCH ${matchId} â†’ completed ${scores.home}-${scores.away}`,
      );

      predictionsGraded += await gradePredictions(
        supabase,
        sport,
        matchId,
        scores.home,
        scores.away,
        known.base_multiplier,
      );
      continue;
    }

    if (isLiveStatus(item)) {
      const scores = extractLiveScores(item);
      const externalFixtureId = Number.isFinite(Number(apiId))
        ? Number(apiId)
        : null;
      const { error } = await supabase
        .from("matches")
        .update({
          status: "live",
          external_fixture_id: externalFixtureId,
          provisional_home_score: scores.home,
          provisional_away_score: scores.away,
          match_minute: formatMatchMinute(item),
          updated_at: nowIso,
        })
        .eq("id", matchId)
        .neq("status", "completed");

      if (error) {
        console.warn(
          `[sync-live-settle] live update failed ${matchId}: ${error.message}`,
        );
        continue;
      }

      liveUpdated++;
      known.status = "live";
    }
  }

  return {
    liveUpdated,
    settled,
    predictionsGraded,
    fetched: catalogItems.length,
  };
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: CORS_HEADERS });
  }

  if (req.method !== "POST" && req.method !== "GET") {
    return jsonResponse({ error: "Method not allowed. Use GET or POST." }, 405);
  }

  const apiKey = getApiSportsKey();
  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  const minIntervalRaw = Deno.env.get("API_SPORTS_MIN_INTERVAL_MS") ?? "7000";
  const minIntervalMs = Number(minIntervalRaw);

  if (!apiKey) {
    return jsonResponse({ error: "Missing API_SPORTS_KEY secret." }, 500);
  }
  if (!supabaseUrl || !serviceRoleKey) {
    return jsonResponse(
      { error: "Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY secret." },
      500,
    );
  }

  const supabase = createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false },
  });

  try {
    const active = await loadActiveCatalogMatches(supabase);

    if (active.length === 0) {
      console.log("No active match window open. 0 API calls made.");
      return jsonResponse({
        skipped: "no_active_window",
        message: "No active match window open. 0 API calls made.",
        activeMatches: 0,
        apiCallsThisRun: 0,
        fetched: 0,
        liveUpdated: 0,
        settled: 0,
        predictionsGraded: 0,
        budget: DAILY_BUDGET_CAP,
      });
    }

    const sportsNeeded = [
      ...new Set(active.map((m) => m.sport)),
    ] as Sport[];

    console.log(
      `[sync-live-settle] Active window: ${active.length} match(es) across [${sportsNeeded.join(", ")}]`,
    );

    const client = new ApiSportsClient({
      supabase,
      apiKey,
      caller: "sync-live-settle",
      budgetCap: DAILY_BUDGET_CAP,
      minIntervalMs: Number.isFinite(minIntervalMs) ? minIntervalMs : 7000,
    });

    const knownById = new Map(active.map((m) => [m.id, m]));

    let liveUpdated = 0;
    let settled = 0;
    let predictionsGraded = 0;
    let fetched = 0;

    for (const sport of sportsNeeded) {
      const outcome = await processSport(sport, client, supabase, knownById);
      liveUpdated += outcome.liveUpdated;
      settled += outcome.settled;
      predictionsGraded += outcome.predictionsGraded;
      fetched += outcome.fetched;
    }

    const usageFb = await client.getUsageToday("football").catch(() => null);
    const usageRb = await client.getUsageToday("rugby").catch(() => null);

    client.logRunSummary({
      activeMatches: active.length,
      sports: sportsNeeded,
      fetched,
      liveUpdated,
      settled,
      predictionsGraded,
      footballCallsToday: usageFb?.calls_made ?? null,
      rugbyCallsToday: usageRb?.calls_made ?? null,
      budgetCap: DAILY_BUDGET_CAP,
    });

    return jsonResponse({
      date: utcDay(),
      sports: sportsNeeded,
      activeMatches: active.length,
      fetched,
      liveUpdated,
      settled,
      predictionsGraded,
      apiCallsThisRun: client.stats.callsThisRun,
      footballCallsToday: usageFb?.calls_made ?? null,
      rugbyCallsToday: usageRb?.calls_made ?? null,
      budget: DAILY_BUDGET_CAP,
      skippedBudget: client.stats.skippedBudget,
      planBlocked: client.stats.planBlocked,
    });
  } catch (err) {
    if (err instanceof UpstreamAuthError) {
      console.error(
        `[sync-live-settle] CRITICAL: Upstream API-Sports authentication failure (HTTP ${err.status})`,
      );
      return jsonResponse(
        {
          error: "Upstream API-Sports authentication failure",
          status: err.status,
          caller: err.caller,
        },
        err.status,
      );
    }
    const message = err instanceof Error ? err.message : String(err);
    console.error("[sync-live-settle] Fatal:", message);
    return jsonResponse({ error: "sync-live-settle failed", detail: message }, 500);
  }
});

/**
 * Shared API-Sports client for Supabase Edge Functions (Deno).
 * Port of scripts/lib/apiSportsClient.ts â€” keep behaviour in sync.
 * Per-sport daily budget (football and rugby each get DAILY_BUDGET_CAP).
 */

import type { SupabaseClient } from "npm:@supabase/supabase-js@2";

export type Sport = "football" | "rugby";

/**
 * Soft safety margin under the verified Pro plan (~7500/day).
 * Override per deploy with API_SPORTS_DAILY_BUDGET if needed.
 */
export const DAILY_BUDGET_CAP = (() => {
  const raw = Deno.env.get("API_SPORTS_DAILY_BUDGET");
  const n = raw != null ? Number(raw) : NaN;
  return Number.isFinite(n) && n > 0 ? n : 7000;
})();

export const FOOTBALL_HOST = "https://v3.football.api-sports.io";
export const RUGBY_HOST = "https://v1.rugby.api-sports.io";

/** Thrown on upstream 401/403 â€” callers must halt the sync and not touch the DB. */
export class UpstreamAuthError extends Error {
  readonly status: number;
  readonly caller: string;

  constructor(status: number, caller: string) {
    super("Upstream API-Sports authentication failure");
    this.name = "UpstreamAuthError";
    this.status = status;
    this.caller = caller;
  }
}

export type ApiSportsResult =
  | {
      ok: true;
      status: number;
      json: any;
      rateLimit: { limit: number | null; remaining: number | null };
      callsMadeToday: number;
      remainingBudget: number;
    }
  | {
      ok: false;
      reason:
        | "budget_exhausted"
        | "network"
        | "http"
        | "plan_blocked"
        | "validation_error"
        | "auth_failure";
      message: string;
      callsMadeToday?: number;
      remainingBudget?: number;
      status?: number;
      json?: any;
    };

export type RunStats = {
  callsThisRun: number;
  skippedBudget: string[];
  skippedCache: string[];
  skippedNoNeed: string[];
  planBlocked: string[];
  validationErrors: string[];
};

export function createRunStats(): RunStats {
  return {
    callsThisRun: 0,
    skippedBudget: [],
    skippedCache: [],
    skippedNoNeed: [],
    planBlocked: [],
    validationErrors: [],
  };
}

/** Sole supported secret name for API-Sports credentials. */
export function getApiSportsKey(): string | null {
  const key = Deno.env.get("API_SPORTS_KEY");
  return typeof key === "string" && key.length > 0 ? key : null;
}

export function classifyApiErrors(
  errors: unknown,
): "none" | "plan_blocked" | "validation_error" {
  if (errors == null) return "none";
  if (Array.isArray(errors) && errors.length === 0) return "none";
  if (typeof errors === "object" && !Array.isArray(errors)) {
    if (Object.keys(errors as object).length === 0) return "none";
  }
  const msg = JSON.stringify(errors);
  if (
    /plan|subscription|upgrade|free plans do not have access|do not have access to this (date|season)/i.test(
      msg,
    )
  ) {
    return "plan_blocked";
  }
  return "validation_error";
}

export function resolveSeasonYear(
  now: Date = new Date(),
  opts: { maxSeason?: number; override?: number | null } = {},
): { season: number; preferred: number; clamped: boolean } {
  if (opts.override != null && Number.isFinite(opts.override)) {
    return {
      season: opts.override,
      preferred: opts.override,
      clamped: false,
    };
  }
  const y = now.getUTCFullYear();
  const m = now.getUTCMonth() + 1;
  const preferred = m >= 7 ? y : y - 1;
  const maxSeason = opts.maxSeason ?? y;
  const season = Math.min(preferred, maxSeason);
  return { season, preferred, clamped: season !== preferred };
}

export function utcDay(d = new Date()): string {
  return d.toISOString().slice(0, 10);
}

export function hostFor(sport: Sport): string {
  return sport === "football" ? FOOTBALL_HOST : RUGBY_HOST;
}

function sleep(ms: number): Promise<void> {
  return new Promise((r) => setTimeout(r, ms));
}

function readRateLimitRemaining(headers: Headers): number | null {
  const rem =
    headers.get("x-ratelimit-requests-remaining") ??
    headers.get("x-ratelimit-remaining");
  if (rem == null || rem === "") return null;
  const n = Number(rem);
  return Number.isFinite(n) ? n : null;
}

function readRateLimitLimit(headers: Headers): number | null {
  const lim =
    headers.get("x-ratelimit-requests-limit") ??
    headers.get("x-ratelimit-limit");
  if (lim == null || lim === "") return null;
  const n = Number(lim);
  return Number.isFinite(n) ? n : null;
}

export class RateLimiter {
  private lastAt = 0;
  remaining: number | null = null;
  limit: number | null = null;

  constructor(private minIntervalMs: number) {}

  noteHeaders(headers: Headers) {
    this.remaining = readRateLimitRemaining(headers);
    this.limit = readRateLimitLimit(headers);
    if (this.remaining != null) {
      console.log(
        `[api-sports] rate-limit remaining=${this.remaining}/${this.limit ?? "?"}`,
      );
      if (this.remaining < 500) {
        console.warn(
          `[api-sports] WARNING: rate-limit remaining below 500 (${this.remaining}/${this.limit ?? "?"})`,
        );
      }
    }
  }

  async waitTurn() {
    const now = Date.now();
    const wait = Math.max(0, this.lastAt + this.minIntervalMs - now);
    if (wait > 0) {
      console.log(`[api-sports] throttling ${wait}msâ€¦`);
      await sleep(wait);
    }
    if (this.remaining != null && this.remaining <= 3) {
      console.warn("[api-sports] upstream remaining â‰¤3 â€” sleeping 60s");
      await sleep(60_000);
    }
    this.lastAt = Date.now();
  }
}

export type ApiSportsClientOptions = {
  supabase: SupabaseClient;
  apiKey: string;
  caller: string;
  budgetCap?: number;
  minIntervalMs?: number;
  stats?: RunStats;
};

export class ApiSportsClient {
  private limiter: RateLimiter;
  private budgetCap: number;
  readonly stats: RunStats;

  constructor(private opts: ApiSportsClientOptions) {
    this.budgetCap = opts.budgetCap ?? DAILY_BUDGET_CAP;
    this.limiter = new RateLimiter(opts.minIntervalMs ?? 7000);
    this.stats = opts.stats ?? createRunStats();
  }

  async getUsageToday(sport: Sport) {
    const { data, error } = await this.opts.supabase.rpc("get_api_quota_usage", {
      p_date: utcDay(),
      p_sport: sport,
    });
    if (error) throw error;
    return data as {
      date: string;
      sport: string;
      calls_made: number;
      last_remaining_from_header: number | null;
      last_limit_from_header: number | null;
    };
  }

  /** Strict post-fetch gate: 401/403 halt the entire sync. */
  private assertUpstreamAuth(res: Response): void {
    if (res.status === 401 || res.status === 403) {
      console.error(
        `[api-sports] CRITICAL: Upstream API-Sports authentication failure (HTTP ${res.status}, caller=${this.opts.caller})`,
      );
      throw new UpstreamAuthError(res.status, this.opts.caller);
    }
  }

  async get(
    sport: Sport,
    apiPath: string,
    params: Record<string, string | number> = {},
    skipLabel?: string,
  ): Promise<ApiSportsResult> {
    const day = utcDay();

    const { data: reserved, error: reserveErr } = await this.opts.supabase.rpc(
      "reserve_api_quota",
      {
        p_date: day,
        p_sport: sport,
        p_budget: this.budgetCap,
        p_caller: this.opts.caller,
      },
    );

    if (reserveErr) {
      return {
        ok: false,
        reason: "http",
        message: `reserve_api_quota failed: ${reserveErr.message}`,
      };
    }

    const reservation = reserved as {
      allowed: boolean;
      calls_made: number;
      remaining_budget: number;
      budget: number;
    };

    if (!reservation.allowed) {
      const label = skipLabel || `${sport} ${apiPath}`;
      this.stats.skippedBudget.push(label);
      console.warn(
        `[api-sports] BUDGET EXHAUSTED (${sport}) â€” skipped ${label} (calls_made=${reservation.calls_made}/${this.budgetCap})`,
      );
      return {
        ok: false,
        reason: "budget_exhausted",
        message: `Daily ${sport} budget ${this.budgetCap} exhausted`,
        callsMadeToday: reservation.calls_made,
        remainingBudget: 0,
      };
    }

    await this.limiter.waitTurn();

    const url = new URL(apiPath, hostFor(sport));
    for (const [k, v] of Object.entries(params)) {
      url.searchParams.set(k, String(v));
    }

    const fetchHeaders = {
      "x-apisports-key": this.opts.apiKey,
      Accept: "application/json",
      "Cache-Control": "no-cache",
      Pragma: "no-cache",
    };

    console.log(
      `[api-sports] GET ${url.pathname}?${url.searchParams} (caller=${this.opts.caller}, sport=${sport}, #${reservation.calls_made}/${this.budgetCap})`,
    );

    let res: Response;
    try {
      res = await fetch(url.toString(), {
        headers: fetchHeaders,
        cache: "no-store",
      });
    } catch (err) {
      return {
        ok: false,
        reason: "network",
        message: err instanceof Error ? err.message : String(err),
        callsMadeToday: reservation.calls_made,
        remainingBudget: reservation.remaining_budget,
      };
    }

    this.limiter.noteHeaders(res.headers);
    this.stats.callsThisRun += 1;
    this.assertUpstreamAuth(res);

    await this.opts.supabase.rpc("record_api_quota_headers", {
      p_date: day,
      p_sport: sport,
      p_remaining: this.limiter.remaining,
      p_limit: this.limiter.limit,
    });

    if (res.status === 429) {
      console.warn("[api-sports] 429 â€” backing off 65s then retrying once");
      await sleep(65_000);
      const retry = await fetch(url.toString(), {
        headers: fetchHeaders,
        cache: "no-store",
      });
      this.limiter.noteHeaders(retry.headers);
      this.assertUpstreamAuth(retry);
      const retryJson = await retry.json().catch(() => ({}));
      return this.wrapOk(retry, retryJson, reservation);
    }

    const json = await res.json().catch(() => ({}));
    if (!res.ok) {
      return {
        ok: false,
        reason: "http",
        message: `HTTP ${res.status}`,
        status: res.status,
        json,
        callsMadeToday: reservation.calls_made,
        remainingBudget: reservation.remaining_budget,
      };
    }

    return this.wrapOk(res, json, reservation);
  }

  private wrapOk(
    res: Response,
    json: any,
    reservation: { calls_made: number; remaining_budget: number },
  ): ApiSportsResult {
    const kind = classifyApiErrors(json?.errors);
    if (kind === "plan_blocked") {
      const msg = JSON.stringify(json.errors);
      console.error(`[api-sports] PLAN BLOCKED: ${msg}`);
      this.stats.planBlocked.push(msg);
      return {
        ok: false,
        reason: "plan_blocked",
        message: msg,
        status: res.status,
        json,
        callsMadeToday: reservation.calls_made,
        remainingBudget: reservation.remaining_budget,
      };
    }
    if (kind === "validation_error") {
      const msg = JSON.stringify(json.errors);
      console.error(
        `[api-sports] VALIDATION ERROR (malformed request â€” aborting this call path): ${msg}`,
      );
      this.stats.validationErrors.push(msg);
      return {
        ok: false,
        reason: "validation_error",
        message: msg,
        status: res.status,
        json,
        callsMadeToday: reservation.calls_made,
        remainingBudget: reservation.remaining_budget,
      };
    }

    return {
      ok: true,
      status: res.status,
      json,
      rateLimit: {
        limit: this.limiter.limit,
        remaining: this.limiter.remaining,
      },
      callsMadeToday: reservation.calls_made,
      remainingBudget: reservation.remaining_budget,
    };
  }

  logRunSummary(extra: Record<string, unknown> = {}) {
    console.log(
      JSON.stringify({
        tag: "api-sports-run-summary",
        caller: this.opts.caller,
        budgetCap: this.budgetCap,
        callsThisRun: this.stats.callsThisRun,
        skippedBudget: this.stats.skippedBudget,
        skippedCache: this.stats.skippedCache,
        skippedNoNeed: this.stats.skippedNoNeed,
        planBlocked: this.stats.planBlocked,
        validationErrors: this.stats.validationErrors,
        ...extra,
      }),
    );
  }

  /** Latest upstream rate-limit remaining observed this client instance. */
  get lastRemaining(): number | null {
    return this.limiter.remaining;
  }
}

export type SystemMetricStatus = "STABLE" | "ERROR";

/**
 * Upsert a health row for the Admin API Status widget.
 * Failures are logged but never throw â€” metrics must not break sync.
 */
export async function reportSystemMetric(
  supabase: SupabaseClient,
  opts: {
    serviceName: string;
    status: SystemMetricStatus;
    apiQuotaRemaining?: number | null;
    errorMessage?: string | null;
  },
): Promise<void> {
  try {
    const { error } = await supabase.from("system_metrics").upsert(
      {
        service_name: opts.serviceName,
        status: opts.status,
        last_sync_time: new Date().toISOString(),
        api_quota_remaining: opts.apiQuotaRemaining ?? null,
        error_message: opts.status === "ERROR"
          ? (opts.errorMessage ?? "Unknown error")
          : null,
        updated_at: new Date().toISOString(),
      },
      { onConflict: "service_name" },
    );
    if (error) {
      console.warn(`[system_metrics] upsert failed: ${error.message}`);
    }
  } catch (err) {
    console.warn(
      `[system_metrics] upsert threw: ${
        err instanceof Error ? err.message : String(err)
      }`,
    );
  }
}

